def transforms(p):
 out=set()
 for k in range(4):
  q={(r,c) for r,c in p}
  for _ in range(k): q={(c,-r) for r,c in q}
  for reflect in (False,True):
   z={(r,-c if reflect else c) for r,c in q}
   mr=min(r for r,c in z); mc=min(c for r,c in z)
   out.add(frozenset((r-mr,c-mc) for r,c in z))
 return out
